(async () => {
    try {
      const token = tokenStore.getAccessToken();
      const locale = localStorage.getItem('i18nextLng') || 'zh-CN';
      const headers: Record<string, string> = {
        Accept: 'text/event-stream',
        'X-Locale': locale,
      };
      if (token) {
        headers.Authorization = `Bearer ${token}`;
      }

      const res = await fetch(`${baseUrl}/sse/agent-runs/${runId}`, {
        headers,
        signal: abortController.signal,
      });

      if (!res.ok || !res.body) {
        throw new Error(`任务实时连接失败（状态 ${res.status}）`);
      }

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true }).replace(/\r\n/g, '\n');

        let boundary = buffer.indexOf('\n\n');
        while (boundary >= 0) {
          const block = buffer.slice(0, boundary);
          buffer = buffer.slice(boundary + 2);
          if (block.trim()) {
            parseSseBlock(block);
          }
          boundary = buffer.indexOf('\n\n');
        }
      }
    } catch (error) {
      if (!abortController.signal.aborted && !closedByEvent) {
        onError(error instanceof Error ? error.message : '任务实时连接失败');
      }
    }
  })

